def stops_in(s,f):
    return [i for i in range(f,len(s)-2,3) if s[i:i+3] in ('TAA','TAG','TGA')]
# stop-to-stop ORFs
def orfs(s,strand,minsize=45):
    res=[]
    for f in range(3):
        st=[-1]+stops_in(s,f)+[len(s)-((len(s)-f)%3)]
        for a,b in zip(st,st[1:]):
            start=a+3; end=b
            n=(end-start)//3
            if n>=minsize:
                res.append((strand,f,start,end,n,tr(s[start:end])))
    return res
