    return set(i for i in range(f,len(s)-2,3) if s[i:i+3] in STOPS)
def runlen(s,start):  # codons until stop from start (in frame)
    n=0; i=start
    while i+3<=len(s):
        if s[i:i+3] in STOPS: return n
        n+=1; i+=3
    return n
